import{_ as i,o as l,c as e,a0 as t}from"./chunks/framework.B7o6dWmz.js";const m=JSON.parse('{"title":"功能一览","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/guide/features.md","filePath":"zh-Hans/guide/features.md","lastUpdated":1793979958000}'),r={name:"zh-Hans/guide/features.md"};function o(n,a,s,h,u,d){return l(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="功能一览" tabindex="-1">功能一览 <a class="header-anchor" href="#功能一览" aria-label="Permalink to &quot;功能一览&quot;">​</a></h1><h2 id="接入" tabindex="-1">接入 <a class="header-anchor" href="#接入" aria-label="Permalink to &quot;接入&quot;">​</a></h2><ul><li>OpenAI：Chat Completions、Responses、Embeddings、Images、Audio、Rerank</li><li>Anthropic Messages、Gemini 原生接口</li><li>三种协议<strong>任意方向互转</strong>，工具调用、图片、thinking、缓存用量都能保真；流式与非流式全覆盖</li><li>Claude Code、各家官方 SDK 直接可用</li></ul><h2 id="上游与路由" tabindex="-1">上游与路由 <a class="header-anchor" href="#上游与路由" aria-label="Permalink to &quot;上游与路由&quot;">​</a></h2><ul><li>上游类型：OpenAI 兼容站（包括各类中转站）、Azure OpenAI、Anthropic、Gemini、AWS Bedrock、Vertex AI</li><li>优先级 + 权重路由，失败自动换渠道；上游说「没有这个模型」也会换渠道，而不是把错误甩给用户</li><li>渠道 Key 自动停用与冷却，定时测速，长回答不截断</li><li>出站地址校验，防 SSRF</li></ul><h2 id="定价与账务" tabindex="-1">定价与账务 <a class="header-anchor" href="#定价与账务" aria-label="Permalink to &quot;定价与账务&quot;">​</a></h2><ul><li>以官方价为锚：全站价、分组价、协议价三层（见 <a href="./pricing">定价与毛利</a>）</li><li>每条渠道记录真实成本，亏本的价格保存不了；定价体检、利润看板</li><li>按 token、按次、长上下文分档计价；缓存读写分别计价</li><li>两阶段账务：预留 → 结算，崩溃可恢复，异常进人工复核</li><li>官方价定时同步与校准，完整调价记录</li></ul><h2 id="运营后台" tabindex="-1">运营后台 <a class="header-anchor" href="#运营后台" aria-label="Permalink to &quot;运营后台&quot;">​</a></h2><ul><li>网关概览：收入、成本、毛利，每日趋势，模型与用户排行，渠道健康</li><li>协议定价：搜一个用户，逐模型或批量设「官方价 N 折」，实时显示毛利</li><li>计费分组由 API Key 决定：专线、特价直接指定到某把 Key</li><li>用量日志、结算复核、余额流水</li><li>菜单与按钮级权限，预置网关运营、财务、客服、只读四个角色；管理员两步验证、后台 IP 白名单</li><li>Prometheus 指标</li></ul><h2 id="用户侧" tabindex="-1">用户侧 <a class="header-anchor" href="#用户侧" aria-label="Permalink to &quot;用户侧&quot;">​</a></h2><ul><li>注册登录：账号密码、手机验证码、邮箱找回密码</li><li>API Key 自助管理：预算、有效期、模型范围、IP 白名单；<strong>Key 只在创建时显示一次</strong>，库里只存哈希</li><li>模型与价格表、用量与账单、接入说明</li></ul><h2 id="收款" tabindex="-1">收款 <a class="header-anchor" href="#收款" aria-label="Permalink to &quot;收款&quot;">​</a></h2><ul><li>管理员手动充值、兑换码</li><li>在线支付：支付宝、四方支付，可扩展；支付密钥只写不读</li><li>邀请奖励</li></ul><h2 id="部署" tabindex="-1">部署 <a class="header-anchor" href="#部署" aria-label="Permalink to &quot;部署&quot;">​</a></h2><ul><li>单个原生可执行文件，运行时无 JVM</li><li>PostgreSQL；Redis 可选</li><li>官方备份脚本与定时任务，支持同步到对象存储</li></ul><h2 id="暂不支持" tabindex="-1">暂不支持 <a class="header-anchor" href="#暂不支持" aria-label="Permalink to &quot;暂不支持&quot;">​</a></h2><ul><li>Midjourney、Suno、视频生成等任务类接口</li><li>用户侧第三方登录（GitHub、OIDC 等）</li><li>PostgreSQL 以外的数据库</li></ul>',17)])])}const f=i(r,[["render",o]]);export{m as __pageData,f as default};
